cat <<'EOF' > cmd/flags.go
package cmd

import (
	"fmt"
	"strings"
)

// flagDef describes one command-line flag for gomplate.
type flagDef struct {
	long       string
	short      string
	kind       string // "string", "stringSlice", "bool"
	def        string // textual default for help
	help       string
	envName    string // shown in help only (e.g., GOMPLATE_LEFT_DELIM)
	metaVar    string // e.g., "datasource", "file"
}

var flagDefs = []flagDef{
	{long: "datasource", short: "d", kind: "stringSlice", metaVar: "datasource",
		help: "datasource in alias=URL form. Specify multiple times to add multiple sources."},
	{long: "datasource-header", short: "H", kind: "stringSlice", metaVar: "header",
		help: "HTTP header field in 'alias=Name: value' form to be provided on HTTP-based data sources. Multiples can be set."},
	{long: "context", short: "c", kind: "stringSlice", metaVar: "datasource",
		help: "pre-load a datasource into the context, in alias=URL form. Use the special alias `.` to set the root context."},
	{long: "plugin", kind: "stringSlice", metaVar: "strings",
		help: "plug in an external command as a function in name=path form. Can be specified multiple times"},
	{long: "file", short: "f", kind: "stringSlice", metaVar: "file", def: "[-]",
		help: "Template file to process. Omit to use standard input, or use --in or --input-dir"},
	{long: "in", short: "i", kind: "string", metaVar: "string",
		help: "Template string to process (alternative to --file and --input-dir)"},
	{long: "input-dir", kind: "string", metaVar: "directory",
		help: "directory which is examined recursively for templates (alternative to --file and --in)"},
	{long: "exclude", kind: "stringSlice", metaVar: "strings",
		help: "glob of files to not parse"},
	{long: "exclude-processing", kind: "stringSlice", metaVar: "strings",
		help: "glob of files to be copied without parsing"},
	{long: "include", kind: "stringSlice", metaVar: "strings",
		help: "glob of files to parse"},
	{long: "out", short: "o", kind: "stringSlice", metaVar: "file", def: "[-]",
		help: "output file name. Omit to use standard output."},
	{long: "template", short: "t", kind: "stringSlice", metaVar: "strings",
		help: "Additional template file(s)"},
	{long: "output-dir", kind: "string", metaVar: "directory", def: ".",
		help: "directory to store the processed templates. Only used for --input-dir"},
	{long: "output-map", kind: "string", metaVar: "string",
		help: "Template string to map the input file to an output path"},
	{long: "chmod", kind: "string", metaVar: "string",
		help: "set the mode for output file(s). Omit to inherit from input file(s)"},
	{long: "exec-pipe", kind: "bool",
		help: "pipe the output to the post-run exec command"},
	{long: "left-delim", kind: "string", metaVar: "delimiter", envName: "GOMPLATE_LEFT_DELIM", def: "{{",
		help: "override the default left-delimiter"},
	{long: "right-delim", kind: "string", metaVar: "delimiter", envName: "GOMPLATE_RIGHT_DELIM", def: "}}",
		help: "override the default right-delimiter"},
	{long: "missing-key", kind: "string", metaVar: "string", def: "error",
		help: "Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value>"},
	{long: "experimental", kind: "bool", envName: "GOMPLATE_EXPERIMENTAL",
		help: "enable experimental features"},
	{long: "verbose", short: "V", kind: "bool",
		help: "output extra information about what gomplate is doing"},
	{long: "config", kind: "string", metaVar: "string", def: ".gomplate.yaml",
		help: "config file (overridden by commandline flags)"},
	{long: "help", short: "h", kind: "bool",
		help: "help for gomplate"},
	{long: "version", short: "v", kind: "bool",
		help: "version for gomplate"},
}

func findDef(name string) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].long == name {
			return &flagDefs[i]
		}
	}
	return nil
}

func findShortDef(ch string) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].short == ch {
			return &flagDefs[i]
		}
	}
	return nil
}

// parsedFlags holds the raw parsed values from the CLI.
type parsedFlags struct {
	values map[string][]string // map of long-name -> slice of values (for bools, single "true"/"false")
	set    map[string]bool
	// post-command (after --)
	postArgs []string
}

func newParsedFlags() *parsedFlags {
	return &parsedFlags{
		values: map[string][]string{},
		set:    map[string]bool{},
	}
}

func (p *parsedFlags) setValue(name, val string) {
	p.values[name] = append(p.values[name], val)
	p.set[name] = true
}

func (p *parsedFlags) getString(name string) string {
	v := p.values[name]
	if len(v) == 0 {
		return ""
	}
	return v[len(v)-1]
}

func (p *parsedFlags) getStringSlice(name string) []string {
	return p.values[name]
}

func (p *parsedFlags) getBool(name string) bool {
	v := p.getString(name)
	return v == "true"
}

func (p *parsedFlags) isSet(name string) bool {
	return p.set[name]
}

// parseArgs parses command-line arguments into parsedFlags.
func parseArgs(args []string) (*parsedFlags, error) {
	pf := newParsedFlags()
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			pf.postArgs = append(pf.postArgs, args[i+1:]...)
			return pf, nil
		}
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			value := ""
			hasValue := false
			if eq := strings.Index(name, "="); eq >= 0 {
				value = name[eq+1:]
				name = name[:eq]
				hasValue = true
			}
			def := findDef(name)
			if def == nil {
				return nil, fmt.Errorf("unknown flag: --%s", name)
			}
			if def.kind == "bool" {
				if hasValue {
					if value == "true" || value == "false" {
						pf.setValue(def.long, value)
					} else {
						return nil, fmt.Errorf("invalid argument %q for %q flag: strconv.ParseBool: parsing %q: invalid syntax", value, "--"+def.long, value)
					}
				} else {
					pf.setValue(def.long, "true")
				}
			} else {
				if !hasValue {
					if i+1 >= len(args) {
						return nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					i++
					value = args[i]
				}
				pf.setValue(def.long, value)
			}
			i++
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			// Handle short flags: -i x, -ix, -abc (combined bools)
			rest := a[1:]
			for len(rest) > 0 {
				ch := rest[:1]
				rest = rest[1:]
				def := findShortDef(ch)
				if def == nil {
					return nil, fmt.Errorf("unknown shorthand flag: %q in -%s", ch, ch)
				}
				if def.kind == "bool" {
					pf.setValue(def.long, "true")
					continue
				}
				// string/stringSlice: consume the rest or next arg
				if len(rest) > 0 {
					if strings.HasPrefix(rest, "=") {
						rest = rest[1:]
					}
					pf.setValue(def.long, rest)
					rest = ""
				} else {
					if i+1 >= len(args) {
						return nil, fmt.Errorf("flag needs an argument: '%s' in -%s", ch, ch)
					}
					i++
					pf.setValue(def.long, args[i])
				}
			}
			i++
			continue
		}
		// positional argument (not expected by gomplate CLI)
		return nil, fmt.Errorf("unknown command %q for %q", a, "gomplate")
	}
	return pf, nil
}
EOF
echo "done"

