cat <<'EOF' > cmd/help.go
package cmd

import (
	"fmt"
	"io"
	"os"
	"strings"
)

const usageHeader = `Process text files with Go templates`

// formatFlagLine returns the help line for a single flagDef, without the description.
func (f *flagDef) leader() string {
	var sb strings.Builder
	if f.short != "" {
		sb.WriteString("  -")
		sb.WriteString(f.short)
		sb.WriteString(", --")
		sb.WriteString(f.long)
	} else {
		sb.WriteString("      --")
		sb.WriteString(f.long)
	}
	if f.metaVar != "" && f.kind != "bool" {
		sb.WriteString(" ")
		sb.WriteString(f.metaVar)
	}
	return sb.String()
}

// describe returns the right-hand-side description of the flag.
func (f *flagDef) describe() string {
	var sb strings.Builder
	sb.WriteString(f.help)
	if f.envName != "" {
		sb.WriteString(" [$")
		sb.WriteString(f.envName)
		sb.WriteString("]")
	}
	if f.def != "" {
		sb.WriteString(" (default ")
		if f.kind == "string" {
			sb.WriteString(`"`)
			sb.WriteString(f.def)
			sb.WriteString(`"`)
		} else {
			sb.WriteString(f.def)
		}
		sb.WriteString(")")
	}
	return sb.String()
}

func printUsage(w io.Writer) {
	fmt.Fprintln(w, "Usage:")
	fmt.Fprintln(w, "  gomplate [flags]")
	fmt.Fprintln(w, "")
	fmt.Fprintln(w, "Flags:")

	maxLeader := 0
	for _, d := range flagDefs {
		if l := len(d.leader()); l > maxLeader {
			maxLeader = l
		}
	}
	for _, d := range flagDefs {
		leader := d.leader()
		desc := d.describe()
		padding := maxLeader - len(leader) + 3
		fmt.Fprintf(w, "%s%s%s\n", leader, strings.Repeat(" ", padding), desc)
	}
}

func printHelp(w io.Writer) {
	fmt.Fprintln(w, usageHeader)
	fmt.Fprintln(w, "")
	printUsage(w)
}

func printVersion(w io.Writer) {
	fmt.Fprintf(w, "gomplate version %s\n", Version)
}

// printFlagError prints the "Error: ..." line and usage, matching cobra.
func printFlagError(errMsg string) {
	printUsage(os.Stdout)
	fmt.Fprintf(os.Stderr, "Error: %s\n", errMsg)
}
EOF
