cat <<'EOF' > cmd/cmd.go
package cmd

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"strings"

	"github.com/hairyhenderson/gomplate/internal/logger"
	"github.com/hairyhenderson/gomplate/render"
)

// Version is the gomplate version string (baked in at build time).
var Version = "0.0.0"

// Run parses CLI args and runs gomplate.
func Run(ctx context.Context, args []string) error {
	pf, err := parseArgs(args)
	if err != nil {
		printFlagError(err.Error())
		// configure a default simple logger just for this final error, matching cobra/gomplate behaviour
		log := logger.New(os.Stderr, "", false)
		log.Error("", "err", err.Error())
		return err
	}

	if pf.getBool("help") {
		printHelp(os.Stdout)
		return nil
	}
	if pf.getBool("version") {
		printVersion(os.Stdout)
		return nil
	}

	// Detect log format from environment (or default to json).
	logFmt := os.Getenv("GOMPLATE_LOG_FORMAT")
	log := logger.New(os.Stderr, logFmt, pf.getBool("verbose"))
	slog.SetDefault(log)

	if pf.getBool("verbose") {
		log.Debug("starting gomplate")
	}

	cfg, err := buildConfig(pf)
	if err != nil {
		log.Error("", "err", err.Error())
		return err
	}

	if pf.getBool("verbose") {
		log.Debug("config is:\n"+cfg.String(), "version", Version, "build", "HEAD")
	}

	if err := cfg.validate(); err != nil {
		log.Error("", "err", fmt.Errorf("failed to validate config: %w", err).Error())
		return err
	}

	start := nowNS()
	errs, rendered := render.Render(ctx, cfg.toRenderConfig())
	duration := nowNS() - start

	if pf.getBool("verbose") {
		log.Debug("completed rendering",
			"templatesRendered", rendered,
			"errors", len(errs),
			"duration", duration)
	}

	if len(errs) > 0 {
		log.Error("", "err", errs[0].Error())
		return errs[0]
	}

	// Post-exec command after --
	if len(pf.postArgs) > 0 {
		if err := runPostExec(ctx, pf.postArgs, cfg); err != nil {
			log.Error("", "err", err.Error())
			return err
		}
	}
	return nil
}

// renderConfig consolidates the final settings for the renderer.
type cliConfig struct {
	In         string
	InSet      bool
	InputFiles []string
	OutputFiles []string
	InputDir   string
	OutputDir  string
	OutputMap  string
	Excludes   []string
	ExcludeProcessing []string
	Includes   []string
	Datasources []string
	Contexts    []string
	Headers    []string
	Templates  []string
	Plugins    []string
	LeftDelim  string
	RightDelim string
	MissingKey string
	Chmod      string
	ExecPipe   bool
	Experimental bool
}

func buildConfig(pf *parsedFlags) (*cliConfig, error) {
	c := &cliConfig{
		LeftDelim:  "{{",
		RightDelim: "}}",
		MissingKey: "error",
		OutputDir:  ".",
	}
	if v, ok := os.LookupEnv("GOMPLATE_LEFT_DELIM"); ok {
		c.LeftDelim = v
	}
	if v, ok := os.LookupEnv("GOMPLATE_RIGHT_DELIM"); ok {
		c.RightDelim = v
	}
	if pf.isSet("left-delim") {
		c.LeftDelim = pf.getString("left-delim")
	}
	if pf.isSet("right-delim") {
		c.RightDelim = pf.getString("right-delim")
	}
	if pf.isSet("missing-key") {
		c.MissingKey = pf.getString("missing-key")
	}
	if pf.isSet("in") {
		c.In = pf.getString("in")
		c.InSet = true
	}
	if pf.isSet("file") {
		c.InputFiles = pf.getStringSlice("file")
	}
	if pf.isSet("out") {
		c.OutputFiles = pf.getStringSlice("out")
	}
	if pf.isSet("input-dir") {
		c.InputDir = pf.getString("input-dir")
	}
	if pf.isSet("output-dir") {
		c.OutputDir = pf.getString("output-dir")
