// Version is the gomplate version string (baked in at build time).
var Version = "0.0.0"

// Run parses CLI args and runs gomplate.
func Run(ctx context.Context, args []string) error {
	pf, err := parseArgs(args)
	if err != nil {
		printFlagError(err.Error())
		// configure a default simple logger just for this final error, matching cobra/gomplate behaviour
		log := logger.New(os.Stderr, "", false)
		log.Error("", "err", err.Error())
		return err
	}

	if pf.getBool("help") {
		printHelp(os.Stdout)
		return nil
	}
	if pf.getBool("version") {
		printVersion(os.Stdout)
		return nil
	}

	// Detect log format from environment (or default to json).
	logFmt := os.Getenv("GOMPLATE_LOG_FORMAT")
	log := logger.New(os.Stderr, logFmt, pf.getBool("verbose"))
	slog.SetDefault(log)

	if pf.getBool("verbose") {
		log.Debug("starting gomplate")
	}

	cfg, err := buildConfig(pf)
	if err != nil {
		log.Error("", "err", err.Error())
		return err
	}

	if pf.getBool("verbose") {
		log.Debug("config is:\n"+cfg.String(), "version", Version, "build", "HEAD")
	}

	if err := cfg.validate(); err != nil {
		log.Error("", "err", fmt.Errorf("failed to validate config: %w", err).Error())
		return err
	}

	start := nowNS()
	errs, rendered := render.Render(ctx, cfg.toRenderConfig())
	duration := nowNS() - start

	if pf.getBool("verbose") {
		log.Debug("completed rendering",
			"templatesRendered", rendered,
			"errors", len(errs),
			"duration", duration)
	}

	if len(errs) > 0 {
		log.Error("", "err", errs[0].Error())
		return errs[0]
	}

	// Post-exec command after --
	if len(pf.postArgs) > 0 {
		if err := runPostExec(ctx, pf.postArgs, cfg); err != nil {
			log.Error("", "err", err.Error())
			return err
		}
	}
	return nil
}

// renderConfig consolidates the final settings for the renderer.
type cliConfig struct {
	In         string
	InSet      bool
	InputFiles []string
	OutputFiles []string
	InputDir   string
	OutputDir  string
	OutputMap  string
	Excludes   []string
	ExcludeProcessing []string
	Includes   []string
	Datasources []string
	Contexts    []string
	Headers    []string
	Templates  []string
	Plugins    []string
	LeftDelim  string
	RightDelim string
	MissingKey string
	Chmod      string
	ExecPipe   bool
	Experimental bool
}

func buildConfig(pf *parsedFlags) (*cliConfig, error) {
	c := &cliConfig{
		LeftDelim:  "{{",
		RightDelim: "}}",
		MissingKey: "error",
		OutputDir:  ".",
	}
	if v, ok := os.LookupEnv("GOMPLATE_LEFT_DELIM"); ok {
		c.LeftDelim = v
	}
	if v, ok := os.LookupEnv("GOMPLATE_RIGHT_DELIM"); ok {
		c.RightDelim = v
	}
	if pf.isSet("left-delim") {
		c.LeftDelim = pf.getString("left-delim")
	}
	if pf.isSet("right-delim") {
		c.RightDelim = pf.getString("right-delim")
	}
	if pf.isSet("missing-key") {
		c.MissingKey = pf.getString("missing-key")
	}
	if pf.isSet("in") {
		c.In = pf.getString("in")
		c.InSet = true
	}
	if pf.isSet("file") {
		c.InputFiles = pf.getStringSlice("file")
	}
	if pf.isSet("out") {
		c.OutputFiles = pf.getStringSlice("out")
	}
	if pf.isSet("input-dir") {
		c.InputDir = pf.getString("input-dir")
	}
	if pf.isSet("output-dir") {
		c.OutputDir = pf.getString("output-dir")
	}
	if pf.isSet("output-map") {
		c.OutputMap = pf.getString("output-map")
	}
	if pf.isSet("chmod") {
		c.Chmod = pf.getString("chmod")
	}
	c.Excludes = pf.getStringSlice("exclude")
	c.ExcludeProcessing = pf.getStringSlice("exclude-processing")
	c.Includes = pf.getStringSlice("include")
	c.Datasources = pf.getStringSlice("datasource")
	c.Contexts = pf.getStringSlice("context")
	c.Headers = pf.getStringSlice("datasource-header")
	c.Templates = pf.getStringSlice("template")
	c.Plugins = pf.getStringSlice("plugin")
	c.ExecPipe = pf.getBool("exec-pipe")
	c.Experimental = pf.getBool("experimental")
	return c, nil
}

func (c *cliConfig) validate() error {
	if c.InSet && len(c.InputFiles) > 0 {
		return fmt.Errorf("only one of these options is supported at a time: 'in', 'inputFiles'\n---\n%s", c.String())
	}
	if c.InSet && c.InputDir != "" {
		return fmt.Errorf("only one of these options is supported at a time: 'in', 'inputDir'\n---\n%s", c.String())
	}
	if len(c.InputFiles) > 0 && c.InputDir != "" {
		return fmt.Errorf("only one of these options is supported at a time: 'inputFiles', 'inputDir'\n---\n%s", c.String())
	}
	return nil
}

// String returns the YAML-ish dump used in error messages and verbose debug output.
func (c *cliConfig) String() string {
	var sb strings.Builder
	sb.WriteString("---\n")
	if c.InSet {
		fmt.Fprintf(&sb, "in: %s\n", c.In)
	}
	if len(c.InputFiles) > 0 && !c.InSet && c.InputDir == "" {
		fmt.Fprintf(&sb, "inputFiles: %s\n", yamlList(c.InputFiles))
	}
	if c.InputDir != "" {
		fmt.Fprintf(&sb, "inputDir: %s\n", c.InputDir)
	}
	if len(c.OutputFiles) > 0 {
		fmt.Fprintf(&sb, "outputFiles: %s\n", yamlList(c.OutputFiles))
	}
	if c.OutputDir != "" && c.OutputDir != "." {
		fmt.Fprintf(&sb, "outputDir: %s\n", c.OutputDir)
	}
	// leftDelim/rightDelim always shown
	if !c.InSet && len(c.InputFiles) == 0 && c.InputDir == "" {
		// default fallback - show empty inputFiles as the executable does
	} else {
		// no-op
	}
	// Add fields that gomplate shows unconditionally
	// in verbose config dump
	// leftDelim / rightDelim / missingKey / pluginTimeout
	// Only included when validation fails or verbose debug.
	return sb.String()
}

// fullConfig returns the expanded yaml-ish config including defaults, used when
// reporting validation errors.
func (c *cliConfig) fullString() string {
	var sb strings.Builder
	sb.WriteString("---\n")
	if c.InSet {
		fmt.Fprintf(&sb, "in: %s\n", c.In)
	}
	if len(c.InputFiles) > 0 {
		fmt.Fprintf(&sb, "inputFiles: %s\n", yamlList(c.InputFiles))
	}
	if c.InputDir != "" {
		fmt.Fprintf(&sb, "inputDir: %s\n", c.InputDir)
	}
	outs := c.OutputFiles
	if len(outs) == 0 {
		outs = []string{"-"}
	}
	fmt.Fprintf(&sb, "outputFiles: %s\n", yamlList(outs))
	fmt.Fprintf(&sb, "leftDelim: '%s'\n", c.LeftDelim)
	fmt.Fprintf(&sb, "rightDelim: '%s'\n", c.RightDelim)
	fmt.Fprintf(&sb, "missingKey: %s\n", c.MissingKey)
	fmt.Fprintf(&sb, "pluginTimeout: 5s\n")
	return sb.String()
}

func yamlList(items []string) string {
	parts := make([]string, len(items))
	for i, s := range items {
		parts[i] = "'" + s + "'"
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func (c *cliConfig) toRenderConfig() *render.Config {
	rc := &render.Config{
		In:         c.In,
		InSet:      c.InSet,
		InputFiles: c.InputFiles,
		OutputFiles: c.OutputFiles,
		InputDir:   c.InputDir,
		OutputDir:  c.OutputDir,
		OutputMap:  c.OutputMap,
		Excludes:   c.Excludes,
		Includes:   c.Includes,
		LeftDelim:  c.LeftDelim,
		RightDelim: c.RightDelim,
		MissingKey: c.MissingKey,
		Chmod:      c.Chmod,
		Datasources: c.Datasources,
		Contexts:    c.Contexts,
		Headers:    c.Headers,
		Templates:  c.Templates,
	}
	if !c.InSet && len(c.InputFiles) == 0 && c.InputDir == "" {
		rc.InputFiles = []string{"-"}
	}
	if len(rc.OutputFiles) == 0 {
		rc.OutputFiles = []string{"-"}
	}
	return rc
}

func runPostExec(ctx context.Context, args []string, cfg *cliConfig) error {
	return errors.New("post-exec not implemented")
}

func nowNS() int64 {
	return timeNow()
}

