// Package logger configures slog handlers for gomplate.
package logger

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"strings"
	"sync"
	"time"
)

// New creates a new *slog.Logger using the given format. If verbose is true,
// Debug level messages are emitted, otherwise only Error.
func New(w io.Writer, format string, verbose bool) *slog.Logger {
	lvl := slog.LevelError
	if verbose {
		lvl = slog.LevelDebug
	}

	format = strings.ToLower(format)
	switch format {
	case "simple":
		return slog.New(&simpleHandler{w: w, level: lvl})
	case "console":
		return slog.New(&consoleHandler{w: w, level: lvl})
	case "logfmt":
		return slog.New(&logfmtHandler{w: w, level: lvl})
	case "json", "":
		return slog.New(slog.NewJSONHandler(w, &slog.HandlerOptions{Level: lvl}))
	default:
		return slog.New(slog.NewJSONHandler(w, &slog.HandlerOptions{Level: lvl}))
	}
}

// -----------------------------------------------------------------------------
// simpleHandler: no time/level, just attrs
// -----------------------------------------------------------------------------
type simpleHandler struct {
	w     io.Writer
	mu    sync.Mutex
	level slog.Level
	attrs []slog.Attr
	group string
}

func (h *simpleHandler) Enabled(_ context.Context, l slog.Level) bool { return l >= h.level }
func (h *simpleHandler) WithAttrs(a []slog.Attr) slog.Handler {
	nh := *h
	nh.attrs = append(append([]slog.Attr{}, h.attrs...), a...)
	return &nh
}
func (h *simpleHandler) WithGroup(name string) slog.Handler {
	nh := *h
	nh.group = name
	return &nh
}
func (h *simpleHandler) Handle(_ context.Context, r slog.Record) error {
	var sb strings.Builder
	if r.Message != "" {
		sb.WriteString(" ")
		sb.WriteString(r.Message)
	}
	for _, a := range h.attrs {
		sb.WriteString(" ")
		writeKV(&sb, a.Key, a.Value)
	}
	r.Attrs(func(a slog.Attr) bool {
		sb.WriteString(" ")
		writeKV(&sb, a.Key, a.Value)
		return true
	})
	sb.WriteByte('\n')
	h.mu.Lock()
	defer h.mu.Unlock()
	_, err := io.WriteString(h.w, " "+strings.TrimPrefix(sb.String(), " "))
	_ = err
	return nil
}

// -----------------------------------------------------------------------------
// consoleHandler: HH:MM:SS LVL msg key=val ...
// -----------------------------------------------------------------------------
type consoleHandler struct {
	w     io.Writer
	mu    sync.Mutex
	level slog.Level
	attrs []slog.Attr
}

func (h *consoleHandler) Enabled(_ context.Context, l slog.Level) bool { return l >= h.level }
func (h *consoleHandler) WithAttrs(a []slog.Attr) slog.Handler {
	nh := *h
	nh.attrs = append(append([]slog.Attr{}, h.attrs...), a...)
	return &nh
}
func (h *consoleHandler) WithGroup(string) slog.Handler { return h }
func (h *consoleHandler) Handle(_ context.Context, r slog.Record) error {
	t := r.Time
	if t.IsZero() {
		t = time.Now()
	}
	lvl := levelShort(r.Level)
	var sb strings.Builder
	fmt.Fprintf(&sb, "%s %s ", t.UTC().Format("15:04:05"), lvl)
	if r.Message != "" {
		sb.WriteString(r.Message)
	}
	for _, a := range h.attrs {
		sb.WriteString(" ")
		writeKV(&sb, a.Key, a.Value)
	}
	r.Attrs(func(a slog.Attr) bool {
		sb.WriteString(" ")
		writeKV(&sb, a.Key, a.Value)
		return true
	})
	sb.WriteByte('\n')
	h.mu.Lock()
	defer h.mu.Unlock()
	_, err := io.WriteString(h.w, sb.String())
	return err
}

// -----------------------------------------------------------------------------
// logfmtHandler: time=... level=... msg=... key=val ...
// -----------------------------------------------------------------------------
type logfmtHandler struct {
	w     io.Writer
	mu    sync.Mutex
	level slog.Level
	attrs []slog.Attr
}

func (h *logfmtHandler) Enabled(_ context.Context, l slog.Level) bool { return l >= h.level }
func (h *logfmtHandler) WithAttrs(a []slog.Attr) slog.Handler {
	nh := *h
	nh.attrs = append(append([]slog.Attr{}, h.attrs...), a...)
	return &nh
}
func (h *logfmtHandler) WithGroup(string) slog.Handler { return h }
func (h *logfmtHandler) Handle(_ context.Context, r slog.Record) error {
	t := r.Time
	if t.IsZero() {
		t = time.Now()
	}
	var sb strings.Builder
	fmt.Fprintf(&sb, "time=%s level=%s msg=%s",
		t.UTC().Format("2006-01-02T15:04:05.000Z"),
		strings.ToUpper(r.Level.String()),
		logfmtQuote(r.Message))
	for _, a := range h.attrs {
		sb.WriteString(" ")
		writeKV(&sb, a.Key, a.Value)
	}
	r.Attrs(func(a slog.Attr) bool {
		sb.WriteString(" ")
		writeKV(&sb, a.Key, a.Value)
		return true
	})
	sb.WriteByte('\n')
	h.mu.Lock()
	defer h.mu.Unlock()
	_, err := io.WriteString(h.w, sb.String())
	return err
}

func levelShort(l slog.Level) string {
	switch {
	case l >= slog.LevelError:
		return "ERR"
	case l >= slog.LevelWarn:
		return "WRN"
	case l >= slog.LevelInfo:
		return "INF"
	default:
		return "DBG"
	}
}

func writeKV(sb *strings.Builder, k string, v slog.Value) {
	sb.WriteString(k)
	sb.WriteString("=")
	sb.WriteString(logfmtQuote(v.String()))
}

func logfmtQuote(s string) string {
	needQuote := false
	for _, r := range s {
		if r == ' ' || r == '"' || r == '\\' || r == '=' || r < 0x20 {
			needQuote = true
			break
		}
	}
	if s == "" {
		return `""`
	}
	if !needQuote {
		return s
	}
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"', '\\':
			sb.WriteByte('\\')
			sb.WriteRune(r)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		default:
			sb.WriteRune(r)
		}
	}
	sb.WriteByte('"')
	return sb.String()
}
