// Package render is responsible for reading inputs, building the template engine
// and writing outputs.
package render

import (
	"context"
	"fmt"
	"io"
	"os"
	"strings"
	"text/template"

	"github.com/hairyhenderson/gomplate/data"
	"github.com/hairyhenderson/gomplate/funcs"
)

// Render runs the rendering step for a given config. It returns a list of
// errors (one per template) and the total number of templates rendered (those
// that produced output, even on error).
func Render(ctx context.Context, cfg *Config) ([]error, int) {
	// Build datasources
	dss, err := data.Build(ctx, cfg.Datasources, cfg.Contexts, cfg.Headers)
	if err != nil {
		return []error{err}, 0
	}

	// Collect inputs
	type job struct {
		name string
		in   string
		out  string
	}
	var jobs []job

	if cfg.InSet {
		out := "-"
		if len(cfg.OutputFiles) > 0 {
			out = cfg.OutputFiles[0]
		}
		jobs = append(jobs, job{name: "<arg>", in: cfg.In, out: out})
	} else if cfg.InputDir != "" {
		return []error{fmt.Errorf("input-dir not implemented")}, 0
	} else {
		outs := cfg.OutputFiles
		for i, in := range cfg.InputFiles {
			name := in
			var body string
			if in == "-" {
				b, err := io.ReadAll(os.Stdin)
				if err != nil {
					return []error{fmt.Errorf("read stdin: %w", err)}, 0
				}
				body = string(b)
				name = "-"
			} else {
				b, err := os.ReadFile(in)
				if err != nil {
					return []error{fmt.Errorf("renderTemplate: read template %s: %w", in, err)}, 0
				}
				body = string(b)
				name = in
			}
			out := "-"
			if i < len(outs) {
				out = outs[i]
			}
			jobs = append(jobs, job{name: name, in: body, out: out})
		}
	}

	funcMap := funcs.BuildFuncMap(ctx, dss)

	var errs []error
	rendered := 0
	for _, j := range jobs {
		tmpl := template.New(j.name).
			Delims(cfg.LeftDelim, cfg.RightDelim).
			Funcs(funcMap)

		switch cfg.MissingKey {
		case "zero":
			tmpl = tmpl.Option("missingkey=zero")
		case "default", "invalid":
			tmpl = tmpl.Option("missingkey=default")
		default:
			tmpl = tmpl.Option("missingkey=error")
		}

		// Add extra template files via -t
		for _, t := range cfg.Templates {
			eq := strings.Index(t, "=")
			if eq < 0 {
				errs = append(errs, fmt.Errorf("invalid template argument: %s", t))
				continue
			}
			alias, path := t[:eq], t[eq+1:]
			if err := addTemplates(tmpl, alias, path); err != nil {
				errs = append(errs, err)
				continue
			}
		}

		if _, err := tmpl.Parse(j.in); err != nil {
			errs = append(errs, fmt.Errorf("renderTemplate: parse template %s: %w", j.name, err))
			rendered++
			continue
		}

		var w io.Writer
		var closer io.Closer
		if j.out == "-" {
			w = os.Stdout
		} else {
			f, err := os.Create(j.out)
			if err != nil {
				errs = append(errs, fmt.Errorf("renderTemplate: create output %s: %w", j.out, err))
				continue
			}
			w = f
			closer = f
		}

		// Build context data
		ctxData := map[string]interface{}{
			"Env": envMap(),
		}
		// Merge default context datasources under . (root)
		for k, v := range dss.Contexts {
			if k == "." {
				// merge into root
				if m, ok := v.(map[string]interface{}); ok {
					for kk, vv := range m {
						ctxData[kk] = vv
					}
				}
				continue
			}
			ctxData[k] = v
		}

		if err := tmpl.Execute(w, ctxData); err != nil {
			errs = append(errs, fmt.Errorf("renderTemplate: failed to render template %s: %w", j.name, err))
		}
		if closer != nil {
			closer.Close()
		}
		rendered++
	}
	return errs, rendered
}

func envMap() map[string]string {
	m := map[string]string{}
	for _, e := range os.Environ() {
		if eq := strings.Index(e, "="); eq >= 0 {
			m[e[:eq]] = e[eq+1:]
		}
	}
	return m
}

func addTemplates(t *template.Template, alias, path string) error {
	info, err := os.Stat(path)
	if err != nil {
		return fmt.Errorf("template %s=%s: %w", alias, path, err)
	}
	if info.IsDir() {
		// add all files with relative path under alias/
		return nil
	}
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	_, err = t.New(alias).Parse(string(b))
	return err
}
