// Sources holds all named datasources.
type Sources struct {
	// url-only datasources resolved on demand
	aliases map[string]string
	cache   map[string]interface{}
	// pre-loaded context datasources (.context flags)
	Contexts map[string]interface{}
}

// Build constructs a Sources from --datasource / --context / --datasource-header flags.
func Build(ctx context.Context, datasources, contexts, headers []string) (*Sources, error) {
	s := &Sources{
		aliases:  map[string]string{},
		cache:    map[string]interface{}{},
		Contexts: map[string]interface{}{},
	}
	for _, d := range datasources {
		alias, u, err := splitAlias(d)
		if err != nil {
			return nil, err
		}
		s.aliases[alias] = u
	}
	for _, c := range contexts {
		alias, u, err := splitAlias(c)
		if err != nil {
			return nil, err
		}
		v, err := s.load(u)
		if err != nil {
			return nil, fmt.Errorf("load context %s: %w", alias, err)
		}
		s.Contexts[alias] = v
	}
	return s, nil
}

func splitAlias(s string) (string, string, error) {
	eq := strings.Index(s, "=")
	if eq < 0 {
		// alias = basename without ext
		base := filepath.Base(s)
		ext := filepath.Ext(base)
		alias := strings.TrimSuffix(base, ext)
		return alias, s, nil
	}
	return s[:eq], s[eq+1:], nil
}

// Get returns the datasource value for a named alias, loading on first access.
func (s *Sources) Get(alias string, args ...string) (interface{}, error) {
	u, ok := s.aliases[alias]
	if !ok {
		return nil, fmt.Errorf("undefined datasource '%s'", alias)
	}
	if v, ok := s.cache[alias]; ok && len(args) == 0 {
		return v, nil
	}
	v, err := s.load(u)
	if err != nil {
		return nil, err
	}
	if len(args) == 0 {
		s.cache[alias] = v
	}
	return v, nil
}

// Exists reports whether an alias is defined.
func (s *Sources) Exists(alias string) bool {
	_, ok := s.aliases[alias]
	return ok
}

func (s *Sources) load(u string) (interface{}, error) {
	parsed, err := url.Parse(u)
	if err != nil || (parsed.Scheme == "" && !strings.Contains(u, "://")) {
		// treat as file path
		return loadFile(u)
	}
	switch parsed.Scheme {
	case "", "file":
		path := parsed.Path
		if path == "" {
			path = u
		}
		return loadFile(path)
	case "stdin":
		b, err := io.ReadAll(os.Stdin)
		if err != nil {
			return nil, err
		}
		ct := parsed.Query().Get("type")
		return parseBytes(b, extFromContentType(ct))
	case "env":
		name := parsed.Host
		if name == "" {
			name = strings.TrimPrefix(parsed.Path, "/")
		}
		v := os.Getenv(name)
		ct := parsed.Query().Get("type")
		return parseBytes([]byte(v), extFromContentType(ct))
	}
	return nil, fmt.Errorf("unsupported datasource scheme: %s", parsed.Scheme)
}

func loadFile(path string) (interface{}, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	ext := strings.ToLower(filepath.Ext(path))
	return parseBytes(b, ext)
}

func parseBytes(b []byte, ext string) (interface{}, error) {
	switch ext {
	case ".json", "json":
		var v interface{}
		if err := json.Unmarshal(b, &v); err != nil {
			return nil, err
		}
		return v, nil
	case ".yaml", ".yml", "yaml":
		return parseYAML(b)
	case ".csv", "csv":
		r := csv.NewReader(strings.NewReader(string(b)))
		rows, err := r.ReadAll()
		if err != nil {
			return nil, err
		}
		out := make([]interface{}, len(rows))
		for i, r := range rows {
			col := make([]interface{}, len(r))
			for j, v := range r {
				col[j] = v
			}
			out[i] = col
		}
		return out, nil
	default:
		// default to text
		return string(b), nil
	}
}

func extFromContentType(ct string) string {
	ct = strings.ToLower(ct)
	switch {
	case strings.Contains(ct, "json"):
		return ".json"
	case strings.Contains(ct, "yaml"):
		return ".yaml"
	case strings.Contains(ct, "csv"):
		return ".csv"
	default:
		return ""
	}
}
