import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
)

// parseYAML parses a YAML document into a Go value (map[string]interface{},
// []interface{}, string, float64, bool, or nil).
func parseYAML(b []byte) (interface{}, error) {
	p := &yamlParser{lines: splitLines(string(b))}
	return p.parseDocument()
}

type yamlParser struct {
	lines []string
	pos   int
}

func splitLines(s string) []string {
	// Remove UTF-8 BOM if present
	s = strings.TrimPrefix(s, "\ufeff")
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	return strings.Split(s, "\n")
}

func (p *yamlParser) parseDocument() (interface{}, error) {
	p.skipBlank()
	if p.pos >= len(p.lines) {
		return nil, nil
	}
	line := p.lines[p.pos]
	trimmed := strings.TrimLeft(line, " ")
	// Document start marker
	if strings.HasPrefix(trimmed, "---") {
		p.pos++
	}
	return p.parseValue(0)
}

func (p *yamlParser) skipBlank() {
	for p.pos < len(p.lines) {
		t := strings.TrimSpace(p.lines[p.pos])
		if t == "" || strings.HasPrefix(t, "#") {
			p.pos++
			continue
		}
		return
	}
}

func indentOf(s string) int {
	for i, r := range s {
		if r != ' ' {
			return i
		}
	}
	return len(s)
}

// parseValue parses a block-level value at the given minimum indent.
func (p *yamlParser) parseValue(minIndent int) (interface{}, error) {
	p.skipBlank()
	if p.pos >= len(p.lines) {
		return nil, nil
	}
	line := p.lines[p.pos]
	indent := indentOf(line)
	if indent < minIndent {
		return nil, nil
	}
	trimmed := strings.TrimLeft(line, " ")
	// Flow scalars on the same line
	if strings.HasPrefix(trimmed, "- ") || trimmed == "-" {
		return p.parseSequence(indent)
	}
	// Detect a mapping: look for "key:" or "key: value"
	if isMappingLine(trimmed) {
		return p.parseMapping(indent)
	}
	// Otherwise it's a flow scalar / flow value
	p.pos++
	return parseScalar(trimmed), nil
}

func isMappingLine(s string) bool {
	// a mapping key is a bareword (or quoted) followed by ':' then end-of-line or space
	i := 0
	// quoted key
	if i < len(s) && (s[i] == '"' || s[i] == '\'') {
		q := s[i]
		i++
		for i < len(s) && s[i] != q {
			if s[i] == '\\' {
				i++
			}
			i++
		}
		if i >= len(s) || s[i] != q {
			return false
		}
		i++
	} else {
		for i < len(s) && s[i] != ':' {
			if s[i] == '#' {
				return false
			}
			i++
		}
	}
	if i >= len(s) || s[i] != ':' {
		return false
	}
	if i+1 >= len(s) {
		return true
	}
	return s[i+1] == ' ' || s[i+1] == '\t' || s[i+1] == 0
}

func (p *yamlParser) parseSequence(indent int) ([]interface{}, error) {
	var out []interface{}
	for p.pos < len(p.lines) {
		p.skipBlank()
		if p.pos >= len(p.lines) {
			break
		}
		line := p.lines[p.pos]
		ind := indentOf(line)
		if ind < indent {
			break
		}
		if ind > indent {
			return nil, fmt.Errorf("yaml: unexpected indent at line %d", p.pos+1)
		}
		t := strings.TrimLeft(line, " ")
		if !(strings.HasPrefix(t, "- ") || t == "-") {
			break
		}
		rest := strings.TrimPrefix(t, "-")
		rest = strings.TrimLeft(rest, " ")
		if rest == "" {
			// nested block on next line(s)
			p.pos++
			v, err := p.parseValue(indent + 1)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
			continue
		}
		if isMappingLine(rest) {
			// compact mapping inside sequence item
			// Replace the current line with the rest, shifted by indent+2
			p.lines[p.pos] = strings.Repeat(" ", indent+2) + rest
			v, err := p.parseMapping(indent + 2)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
			continue
		}
		// scalar / flow value
		p.pos++
		out = append(out, parseScalar(rest))
	}
	return out, nil
