func (p *yamlParser) parseMapping(indent int) (map[string]interface{}, error) {
	out := map[string]interface{}{}
	for p.pos < len(p.lines) {
		p.skipBlank()
		if p.pos >= len(p.lines) {
			break
		}
		line := p.lines[p.pos]
		ind := indentOf(line)
		if ind < indent {
			break
		}
		if ind > indent {
			return nil, fmt.Errorf("yaml: unexpected indent at line %d", p.pos+1)
		}
		t := strings.TrimLeft(line, " ")
		if !isMappingLine(t) {
			break
		}
		key, rest := splitMappingKey(t)
		rest = strings.TrimLeft(rest, " ")
		if rest == "" {
			p.pos++
			v, err := p.parseValue(indent + 1)
			if err != nil {
				return nil, err
			}
			out[key] = v
			continue
		}
		p.pos++
		out[key] = parseScalar(rest)
	}
	return out, nil
}

func splitMappingKey(s string) (string, string) {
	i := 0
	if i < len(s) && (s[i] == '"' || s[i] == '\'') {
		q := s[i]
		i++
		start := i
		for i < len(s) && s[i] != q {
			i++
		}
		key := s[start:i]
		if i < len(s) {
			i++
		}
		if i < len(s) && s[i] == ':' {
			i++
		}
		return key, s[i:]
	}
	for i < len(s) && s[i] != ':' {
		i++
	}
	key := strings.TrimSpace(s[:i])
	if i < len(s) {
		i++
	}
	return key, s[i:]
}

// parseScalar parses a single-line YAML scalar expression. Supports flow
// sequences `[a, b, c]` and flow maps `{a: 1}`.
func parseScalar(s string) interface{} {
	s = strings.TrimRight(s, " \t")
	if s == "" {
		return ""
	}
	// strip trailing comment
	if idx := indexOfComment(s); idx >= 0 {
		s = strings.TrimRight(s[:idx], " \t")
	}
	if strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]") {
		return parseFlowSeq(s[1 : len(s)-1])
	}
	if strings.HasPrefix(s, "{") && strings.HasSuffix(s, "}") {
		return parseFlowMap(s[1 : len(s)-1])
	}
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		u, err := strconv.Unquote(s)
		if err == nil {
			return u
		}
		return s[1 : len(s)-1]
	}
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return strings.ReplaceAll(s[1:len(s)-1], "''", "'")
	}
	switch strings.ToLower(s) {
	case "null", "~", "":
		return nil
	case "true", "yes", "on":
		return true
	case "false", "no", "off":
		return false
	}
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		return i
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f
	}
	return s
}

func indexOfComment(s string) int {
	inSingle, inDouble := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\'' && !inDouble {
			inSingle = !inSingle
		} else if c == '"' && !inSingle {
			inDouble = !inDouble
		} else if c == '#' && !inSingle && !inDouble {
			if i > 0 && !unicode.IsSpace(rune(s[i-1])) {
				continue
			}
			return i
		}
	}
	return -1
}

func parseFlowSeq(s string) []interface{} {
	parts := splitFlow(s)
	out := make([]interface{}, 0, len(parts))
	for _, p := range parts {
		out = append(out, parseScalar(strings.TrimSpace(p)))
	}
	return out
}

func parseFlowMap(s string) map[string]interface{} {
	parts := splitFlow(s)
	out := map[string]interface{}{}
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		key, rest := splitMappingKey(p)
		rest = strings.TrimLeft(rest, " ")
		out[key] = parseScalar(rest)
	}
	return out
}

func splitFlow(s string) []string {
	var parts []string
	depth := 0
	inSingle, inDouble := false, false
	last := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '\'' && !inDouble:
			inSingle = !inSingle
		case c == '"' && !inSingle:
			inDouble = !inDouble
		case inSingle || inDouble:
			continue
		case c == '[' || c == '{':
			depth++
		case c == ']' || c == '}':
			depth--
		case c == ',' && depth == 0:
			parts = append(parts, s[last:i])
			last = i + 1
		}
	}
	parts = append(parts, s[last:])
	return parts
}
