func parseFlowMap(s string) map[string]interface{} {
	parts := splitFlow(s)
	out := map[string]interface{}{}
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		key, rest := splitMappingKey(p)
		rest = strings.TrimLeft(rest, " ")
		out[key] = parseScalar(rest)
	}
	return out
}

func splitFlow(s string) []string {
	var parts []string
	depth := 0
	inSingle, inDouble := false, false
	last := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '\'' && !inDouble:
			inSingle = !inSingle
		case c == '"' && !inSingle:
			inDouble = !inDouble
		case inSingle || inDouble:
			continue
		case c == '[' || c == '{':
			depth++
		case c == ']' || c == '}':
			depth--
		case c == ',' && depth == 0:
			parts = append(parts, s[last:i])
			last = i + 1
		}
	}
	parts = append(parts, s[last:])
