	fm["split"] = func(sep, s string) []string { return strings.Split(s, sep) }
	fm["join"] = func(sep string, v []interface{}) string {
		parts := make([]string, len(v))
		for i, x := range v {
			parts[i] = fmt.Sprintf("%v", x)
		}
		return strings.Join(parts, sep)
	}
	fm["indent"] = func(args ...interface{}) (string, error) {
		switch len(args) {
		case 2:
			return indentFn(toInt(args[0]), " ", fmt.Sprintf("%v", args[1])), nil
		case 3:
			return indentFn(toInt(args[0]), fmt.Sprintf("%v", args[1]), fmt.Sprintf("%v", args[2])), nil
		}
		return "", fmt.Errorf("indent: expected 2 or 3 arguments")
