		return v, err
	}
	fm["json"] = func(s string) (interface{}, error) {
		var v interface{}
		err := json.Unmarshal([]byte(s), &v)
		return v, err
	}
	fm["yaml"] = func(s string) (interface{}, error) { return data.ParseYAML([]byte(s)) }

	fm["default"] = defaultFn
	fm["coalesce"] = coalesceFn
}

func seqFn(args ...int64) ([]int64, error) {
	switch len(args) {
	case 1:
		return math.Seq(1, args[0], 1), nil
	case 2:
		step := int64(1)
		if args[0] > args[1] {
			step = 1
		}
		return math.Seq(args[0], args[1], step), nil
	case 3:
		return math.Seq(args[0], args[1], args[2]), nil
	}
