	}
	return value
}

func coalesceFn(args ...interface{}) interface{} {
	for _, a := range args {
		if !isEmpty(a) {
			return a
		}
	}
	return nil
}

func isEmpty(v interface{}) bool {
	if v == nil {
		return true
	}
	switch vv := v.(type) {
	case string:
		return vv == ""
	case bool:
		return !vv
	case int, int32, int64:
		return false
	case float32, float64:
		return false
	case []interface{}:
		return len(vv) == 0
	case map[string]interface{}:
		return len(vv) == 0
	}
	return false
}
