package funcs

import (
	"fmt"
	"math"
	"strconv"

	gmath "github.com/hairyhenderson/gomplate/math"
)

// mathNS is the math.* namespace.
type mathNS struct{}

// MathNS is the instance exposed in templates as `math`.
var MathNS = mathNS{}

func (mathNS) Add(args ...interface{}) interface{}   { return addFn(args...) }
func (mathNS) Sub(a, b interface{}) interface{}      { return subFn(a, b) }
func (mathNS) Mul(args ...interface{}) interface{}   { return mulFn(args...) }
func (mathNS) Div(a, b interface{}) float64          { return toFloat(a) / toFloat(b) }
func (mathNS) Abs(a interface{}) interface{}         { return math.Abs(toFloat(a)) }
func (mathNS) Ceil(a interface{}) float64            { return math.Ceil(toFloat(a)) }
func (mathNS) Floor(a interface{}) float64           { return math.Floor(toFloat(a)) }
func (mathNS) Round(a interface{}) float64           { return math.Round(toFloat(a)) }
func (mathNS) Max(args ...interface{}) interface{}   { return maxFn(args...) }
func (mathNS) Min(args ...interface{}) interface{}   { return minFn(args...) }
func (mathNS) Seq(args ...int64) ([]int64, error)    { return seqFn(args...) }
func (mathNS) IsInt(a interface{}) bool              { _, err := strconv.ParseInt(fmt.Sprintf("%v", a), 10, 64); return err == nil }
func (mathNS) IsFloat(a interface{}) bool {
	_, err := strconv.ParseFloat(fmt.Sprintf("%v", a), 64)
	return err == nil
}
func (mathNS) IsNum(a interface{}) bool {
	_, err := strconv.ParseFloat(fmt.Sprintf("%v", a), 64)
	return err == nil
}
func (mathNS) Pow(a, b interface{}) float64 { return math.Pow(toFloat(a), toFloat(b)) }

