package funcs

import "os"

type envNS struct{}

var EnvNS = envNS{}

func (envNS) Getenv(name string, defaultValue ...string) string {
	if v, ok := os.LookupEnv(name); ok {
		return v
	}
	if len(defaultValue) > 0 {
		return defaultValue[0]
	}
	return ""
}

func (envNS) Env() map[string]string {
	m := map[string]string{}
	for _, kv := range os.Environ() {
		for i := 0; i < len(kv); i++ {
			if kv[i] == '=' {
				m[kv[:i]] = kv[i+1:]
				break
			}
		}
	}
	return m
}
