package funcs

import "os"

type fileNS struct{}

var FileNS = fileNS{}

func (fileNS) Read(path string) (string, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

func (fileNS) Exists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

func (fileNS) Stat(path string) (os.FileInfo, error) {
	return os.Stat(path)
}

func (fileNS) Write(path, content string) error {
	return os.WriteFile(path, []byte(content), 0644)
}

func (fileNS) ReadDir(path string) ([]string, error) {
	entries, err := os.ReadDir(path)
	if err != nil {
		return nil, err
	}
	out := make([]string, len(entries))
	for i, e := range entries {
		out[i] = e.Name()
	}
	return out, nil
}

func (fileNS) Walk(path string) ([]string, error) {
	var out []string
	// minimal walk - not recursive TreeWalk
	entries, err := os.ReadDir(path)
	if err != nil {
		return nil, err
	}
	for _, e := range entries {
		out = append(out, e.Name())
	}
	return out, nil
}
