	case 1:
		cond = truthy(args[0])
	case 2:
		msg = fmt.Sprintf("%v", args[0])
		cond = truthy(args[1])
	default:
		return "", fmt.Errorf("test.Assert: expected 1 or 2 args")
	}
	if !cond {
		if msg != "" {
			return "", fmt.Errorf("assertion failed: %s", msg)
		}
		return "", fmt.Errorf("assertion failed")
	}
	return "", nil
