package funcs

import (
	"crypto/sha1"
	"crypto/sha256"
	"crypto/sha512"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
)

func unmarshalJSON(b []byte, v interface{}) error {
	return json.Unmarshal(b, v)
}

func sha1Sum(b []byte) [20]byte   { return sha1.Sum(b) }
func sha256Sum(b []byte) [32]byte { return sha256.Sum256(b) }
func sha512Sum(b []byte) [64]byte { return sha512.Sum512(b) }

// toYAML is a very small YAML serializer supporting the subset that
// gomplate typically produces (strings, numbers, bools, nil, maps, slices).
func toYAML(v interface{}, indent int) string {
	switch vv := v.(type) {
	case nil:
		return "null"
	case bool:
		if vv {
			return "true"
		}
		return "false"
	case string:
		return yamlQuoteIfNeeded(vv)
	case map[string]interface{}:
		if len(vv) == 0 {
			return "{}"
		}
		keys := make([]string, 0, len(vv))
		for k := range vv {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		var sb strings.Builder
		for i, k := range keys {
			if i > 0 || indent > 0 {
				sb.WriteString("\n")
			}
			sb.WriteString(strings.Repeat("  ", indent))
			sb.WriteString(k)
			sb.WriteString(": ")
			child := toYAML(vv[k], indent+1)
			if strings.Contains(child, "\n") {
				sb.WriteString("\n")
				for _, line := range strings.Split(child, "\n") {
					sb.WriteString(strings.Repeat("  ", indent+1))
					sb.WriteString(line)
					sb.WriteString("\n")
				}
			} else {
				sb.WriteString(child)
			}
		}
		return strings.TrimRight(sb.String(), "\n")
	case []interface{}:
		if len(vv) == 0 {
			return "[]"
		}
		var sb strings.Builder
		for _, x := range vv {
			sb.WriteString("\n")
			sb.WriteString(strings.Repeat("  ", indent))
			sb.WriteString("- ")
			sb.WriteString(toYAML(x, indent+1))
		}
		return strings.TrimLeft(sb.String(), "\n")
	default:
		return fmt.Sprintf("%v", vv)
	}
}

func yamlQuoteIfNeeded(s string) string {
	if s == "" {
		return `""`
	}
	if strings.ContainsAny(s, ":#\"'{}[],&*!|>%@\n\t") {
		return fmt.Sprintf("%q", s)
	}
	return s
}
EOF

